import{_ as l,l as r,o as e,c as d,v as t,p as n,x as i,d as s,i as m,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"嵌入作为查找","description":"","frontmatter":{"title":"嵌入作为查找","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/embed-as-lookup-motive.md","filePath":"llm/embed-as-lookup-motive.md","lastUpdated":1789023840000}'),p={name:"llm/embed-as-lookup-motive.md"};function E(_,a,c,b,u,A){const o=r("Mermaid");return e(),d("div",null,[a[1]||(a[1]=t('<h1 id="嵌入作为查找" tabindex="-1">嵌入作为查找 <a class="header-anchor" href="#嵌入作为查找" aria-label="Permalink to &quot;嵌入作为查找&quot;">​</a></h1><div class="epigraph"><p>编号没有度量；进入矩阵乘之前，每个 id 只是在一张表里选一行。那一次选择叫查找，不叫第一层稠密乘。</p><footer>—— 据 Bengio et al., JMLR 2003；Mikolov et al., 2013 整理</footer></div><p><a href="/llm/why-subword">子词的动机</a>把符号粒度收成有限片段。本课不重写切分。缺口是：id 仍是整数，不能做 \\(Wx\\)。方法是查找表 \\(E\\in\\mathbb{R}^{|V|\\times d}\\)，\\(e_t=E[t]\\)。主干稍后的<a href="/llm/embedding-lookup">Token 嵌入查找</a>会在 Transformer 宽度上再写一遍工程细节；本课在基础课里先把「离散 \\(\\to\\) 向量」的接口钉住，并交给循环网络去吃这些向量。不要在这里展开位置编码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分布假设与 skip-gram 已经把词当成向量来训，但接口常常被说成「one-hot 乘 \\(E\\)」。代数上对，实现上错：one-hot 长度为 \\(|V|\\)，不能物化。正确接口是 gather：用整数下标取出第 \\(t\\) 行。缺口是把这一次取出写成所有序列模型的输入约定——RNN、稍后的注意力、分类头之前，看见的都是 \\(X\\in\\mathbb{R}^{n\\times d}\\)，而不是 id 本身。</p><p>梯度是 scatter：只更新被点到的行。这与 NEG 的稀疏更新、与长尾行学不透，是同一机制。子词提高的是「哪些行会被点到」，不改变算子是查找。</p><h3 id="查找不是把-id-当成标量特征" tabindex="-1">查找不是把 id 当成标量特征 <a class="header-anchor" href="#查找不是把-id-当成标量特征" aria-label="Permalink to &quot;查找不是把 id 当成标量特征&quot;">​</a></h3><p>把编号除以 \\(|V|\\) 送进网络，或把 id 嵌入成 \\(\\sin(\\mathrm{id})\\)，会把任意的词表次序当成度量。词表次序通常是频率或哈希，没有语义。任何对编号光滑的函数都在注入这份假几何。离散身份只能当下标。这与第一课「形状先于算子」并列：类型先于算子——id 是索引类型，不是 \\(\\mathbb{R}\\)。</p><p><span class="marginnote">padding 也会查出一行。随后必须用掩码挡住损失与状态更新，否则 PAD 行会被学成「句末平均噪声」。特殊符号各占合法 id，不是越界。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(T\\in\\{0,\\ldots,|V|-1\\}^{B\\times n}\\) 经查找得 \\(X\\in\\mathbb{R}^{B\\times n\\times d}\\)，\\(X_{b,i}=E_{T_{b,i}}\\)。同一 id 在不同位置取出同一行；位置之间的差异必须由后课的循环状态或位置编码提供。初始化 \\(E\\) 用小方差高斯，避免初始向量过大。训练目标可以是 skip-gram、可以是下一词分类；查找层不关心下游损失的名字，只提供 \\(X\\)。越界 id 是协议错误，不是 UNK：UNK 有合法行。</p>',11)),(e(),n(h,null,{default:i(()=>[m(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ID%5B%22%E7%A6%BB%E6%95%A3%20id%22%5D%20--%3E%20GATH%5B%22%E6%8C%89%E8%A1%8C%20gather%22%5D%0A%20%20E%5B%22%E8%A1%A8%20E%22%5D%20--%3E%20GATH%0A%20%20GATH%20--%3E%20X%5B%22%E5%90%84%E4%BD%8D%E7%BD%AE%E4%B8%8A%E7%9A%84%E5%90%91%E9%87%8F%22%5D%0A%20%20X%20--%3E%20SEQ%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ARNN%20%E6%B2%BF%E4%BD%8D%E7%BD%AE%E8%AF%BB%20X%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>查找把监督按符号身份分开，几何由下游如何使用 \\(X\\) 来塑造。若下游是窗口 softmax，\\(E\\) 学成静态词型向量；若下游是 RNN 语言模型，\\(E\\) 仍是静态行，但会被上下文相关的隐状态继续改写——改写发生在状态里，不发生在表内同一行随位置变化。一行一词型（或一子词型），这是本课的边界。上下文相关表示是注意力之后的事。</p><p>同一批里重复出现的 id 取出同一行，再沿位置复制进 \\(X\\)。这不是广播规则的新例子，而是「身份相同则向量相同」。要让同一符号在句首句末不同，必须靠后课的 \\(h_t\\) 或位置通道去改写副本，不能指望 \\(E\\) 为每个下标存一行——那张表按词表索引，不按时间索引。</p><p>批量里只出现一小撮 id，计算稀疏、存储稠密。优化器若为每一行存动量，内存按 \\(|V|d\\) 乘系数。这是工程账，机制上记住即可。与负采样课衔接：NEG 每步只碰少数行，查找的反向本来就是 scatter，两者一致。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定义位置编码，不定义 SDPA，不与主干嵌入课抢写 tying、多语言模型。下一课<a href="/llm/rnn-long-range">RNN 与长程依赖</a>假定输入已是向量序列，问状态如何沿时间走。后课默认：序列模型的输入是查找得到的 \\(X\\)，编号从不直接进入 GEMM。共享输入输出嵌入是主干课的缺口，本课的 \\(E\\) 只负责输入侧。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>离散 id 通过 \\(E[t]\\) 变成向量，实现是 gather 不是稠密 one-hot 乘。</li><li>编号无度量；对 id 的光滑函数会注入假几何。</li><li>梯度只更新被点到的行；PAD 必须掩掉。</li><li>表内一行不随位置改变；位置差异交给后课的状态或位置编码。</li><li>同一 id 取出同一行，再沿位置复制；身份相同则向量相同。</li><li>出处：Bengio et al., 2003；Mikolov et al., 2013。</li></ul>',8))])}const T=l(p,[["render",E]]);export{B as __pageData,T as default};
